do $$
declare
  v_page_data jsonb := $tp${"hero": {"image": "https://media.profoxwebdesigner.com/media/brand-visuals/2026-08/website-integrated-capabilities.webp", "title": "Refer Great People.", "ctaUrl": "/talent-partner", "ctaText": "Become a Talent Partner", "highlight": "Earn From Their First Successful Results.", "subheading": "PROFOX TALENT PARTNER PROGRAM", "description": "Introduce qualified Sales, Content, UI/UX Design, or Web Development professionals to ProFox through your personal tracked referral link. When someone you refer joins ProFox and produces a qualifying result, you earn according to the active reward plan for their role."}, "quoteHeading": "How Long Do You Earn From One Referral?", "quoteDescription": "This is a milestone-based referral reward program — not a lifetime recurring commission program.", "quote": "After {{salesCount}} qualifying sales, the sales-commission portion of that referral is complete. You do not continue receiving commission from every future sale made by that Sales Representative.", "quoteAuthor": "After {{projectCount}} qualifying completed projects, that referral’s project-reward cycle is complete. You do not continue receiving commission from every future project completed by that professional.", "frictionTitle": "Final Retention Reward", "frictionDescription": "When the applicable retention and salary-transition conditions are met.", "howWeHelpEyebrow": "WHY PARTNER WITH PROFOX", "howWeHelpTitle": "A Simple Way to Turn Great Introductions Into Additional Income.", "howWeHelpDesc": "You may already know talented people looking for their next opportunity. ProFox gives you a structured way to earn when a direct referral genuinely succeeds, while our recruitment, performance, reward, and payout systems handle the rest.", "howWeHelpButtonText": "See How You Earn", "howWeHelpButtonUrl": "#how-you-earn", "howWeHelp": [{"title": "Your Own Trackable Referral Links", "desc": "Every eligible role has a referral link connected to your Talent Partner account, so valid introductions can be tracked and protected.", "features": ["Role-specific referral links", "First-valid-referral protection", "Visit and referral tracking"]}, {"title": "Rewards Tied to Real Results", "desc": "You earn when your referred professional reaches a qualifying sales, project, or retention milestone—not simply for generating a click or application.", "features": ["Sales or project-based qualification", "Admin-controlled reward plans", "Retention rewards where applicable"]}, {"title": "Transparent Progress & Earnings", "desc": "Follow your referred candidates, qualifying results, reward status, and payout history from your Talent Partner dashboard.", "features": ["Referral progress", "Reward status", "Payout history"]}, {"title": "A Direct Partner Relationship", "desc": "You earn from professionals you directly refer. There is no downline, recruitment chain, or MLM-style commission structure.", "features": ["No downline", "No duplicate ownership", "Clear attribution rules"]}], "processEyebrow": "HOW IT WORKS", "processTitle": "From One Introduction to a Real Reward — in Four Simple Steps.", "processDescription": "You find the right person and make the introduction. ProFox handles the hiring, training, performance tracking, reward calculation, and payout process.", "ourProcess": [{"step": "01", "title": "Join the Talent Partner Program", "desc": "Create your Talent Partner account and complete the required payout setup. Once your account is approved and activated, your referral tools become available."}, {"step": "02", "title": "Choose a Role & Share Your Personal Link", "desc": "Pick an eligible ProFox role from your dashboard and share your unique referral link with someone you genuinely believe could succeed in that role."}, {"step": "03", "title": "ProFox Handles the Hiring", "desc": "If your referral applies, ProFox handles screening, assessments, agreements, training, certification, and activation. You can follow the referral’s progress from your dashboard."}, {"step": "04", "title": "They Produce Results. You Earn — Up to the Defined Limit.", "desc": "Sales referrals can earn across the first {{salesCount}} qualifying sales and, when enabled, a final retention reward. Project-based referrals can earn across the first {{projectCount}} qualifying completed projects. Once those configured milestones are complete, that referral’s current reward cycle is complete."}], "pricingEyebrow": "LIVE REWARDS BY ROLE", "pricingTitle": "Know What You Can Earn Before You Refer Anyone.", "pricingDescription": "No vague promises. The reward plan for each eligible role is loaded directly from the active Talent Partner Admin configuration, so you can see what has to happen and what you can earn when it does.", "challengesEyebrow": "QUALITY OVER VOLUME", "challengesTitle": "You Don’t Need Hundreds of Referrals. You Need the Right Ones.", "challengesDescription": "A strong Talent Partner introduces people who genuinely have the skills, communication, work ethic, and potential to succeed at ProFox.", "challenges": ["Refer people you know, source, or genuinely identify as suitable for an eligible ProFox opportunity.", "Always use your personal role-specific referral link so valid attribution can be tracked correctly.", "Do not refer yourself, create duplicate applications, or attempt to replace another Talent Partner’s valid attribution.", "Make the introduction, but do not promise a job. ProFox makes all hiring, activation, and performance decisions.", "Protect candidate privacy and share only the information genuinely required for a legitimate referral."], "faqsTitle": "Talent Partner FAQs", "faqsDesc": "Everything important should be clear before you start referring people. Live reward values and timing shown in these answers come from the current Talent Partner Admin configuration.", "faqs": [{"question": "When do I provide payout details?", "answer": "Payout setup is part of Talent Partner onboarding. You must submit a valid payout method before referral work is enabled. ProFox verifies the payout profile before an actual payment can be processed."}, {"question": "Will I earn commission from every future sale made by the salesperson I refer?", "answer": "No. Under the current Sales referral plan, you earn only from the first {{salesCount}} qualifying verified sales: {{salesRewards}}. After those qualifying sales are complete, you do not continue receiving sales commission from that person’s future sales. When enabled, you may still qualify for the separate one-time {{retentionReward}} retention reward after {{retentionMonths}} months if the applicable retention and salary-transition conditions are met."}, {"question": "Is the retention reward recurring?", "answer": "No. It is a one-time final reward for that referral. When enabled, it becomes eligible only after the referred Sales Representative completes the configured {{retentionMonths}}-month retention period and meets the applicable retention and salary-transition conditions."}, {"question": "How many projects can I earn from for Content, Design, or Development referrals?", "answer": "Under the current project-based reward plan, you can earn from the referred professional’s first {{projectCount}} qualifying completed projects: {{projectRewards}}. After those configured project milestones are complete, you do not continue earning from that person’s future projects."}, {"question": "How long does referral attribution last?", "answer": "The current referral tracking window is {{attributionDays}} days. A valid tracked referral can qualify for attribution when the candidate applies within the applicable tracking window."}, {"question": "Do I earn simply because someone applies?", "answer": "No. An application can establish the referral relationship, but a reward is created only when the referred professional reaches the qualifying business result defined for their role."}, {"question": "Can another Talent Partner claim the same candidate later?", "answer": "The program uses a first-valid-referral rule. Once a candidate’s application is validly attributed, another Talent Partner cannot simply overwrite that ownership with a later referral."}, {"question": "When do I actually get paid?", "answer": "A qualifying reward first moves through the applicable approval and payout controls. The current standard payout hold is {{payoutHoldDays}} days. Your dashboard shows the reward and payout status throughout the process."}, {"question": "Is this an MLM or downline program?", "answer": "No. There are no levels or downlines. You earn only from qualifying outcomes produced by professionals you directly referred."}], "ctaEyebrow": "BUILD A STRONGER PROFOX NETWORK", "ctaTitle": "You May Already Know Your Next Successful Referral.", "ctaDescription": "Think of someone who could genuinely succeed in Sales, Content, UI/UX Design, or Web Development. Introduce them through your personal ProFox referral link. They get an opportunity to succeed, ProFox gets stronger talent, and when your referral creates qualifying results, you get rewarded.", "ctaButtonText": "Become a Talent Partner", "ctaUrl": "/talent-partner"}$tp$::jsonb;
begin
  update public.content
  set data = (
    select coalesce(jsonb_agg(
      case
        when item.value->>'id' = 'talent-partner-program' then
          item.value || jsonb_build_object(
            'title', 'Talent Partner Program',
            'slug', 'talent-partner-program',
            'status', 'published',
            'template', 'talent-partner-program',
            'heroTitle', v_page_data->'hero'->>'title',
            'heroSubtitle', v_page_data->'hero'->>'description',
            'coverImage', v_page_data->'hero'->>'image',
            'serviceDetailData', v_page_data
          )
        else item.value
      end
      order by item.ordinality
    ), '[]'::jsonb)
    from jsonb_array_elements(public.content.data) with ordinality as item(value, ordinality)
  )
  where id = 'customPages';

  update public.content
  set data = (
    select coalesce(jsonb_agg(
      case
        when item.value->>'id' = 'talent-partner-program' then
          item.value || jsonb_build_object(
            'name', 'Talent Partner Program Blueprint',
            'type', 'service-detail',
            'description', 'Conversion-focused Talent Partner page. Marketing copy remains editable in Template Manager while reward values, qualifying counts, retention timing, attribution, payout hold, and role publication stay live from Talent Partner Admin.',
            'defaultData', v_page_data
          )
        else item.value
      end
      order by item.ordinality
    ), '[]'::jsonb)
    from jsonb_array_elements(public.content.data) with ordinality as item(value, ordinality)
  )
  where id = 'template_blueprints';

  if not exists (
    select 1
    from public.content c,
         jsonb_array_elements(c.data) item
    where c.id = 'customPages'
      and item->>'id' = 'talent-partner-program'
  ) then
    raise exception 'Talent Partner custom page is missing; refusing to create a duplicate page.';
  end if;

  if not exists (
    select 1
    from public.content c,
         jsonb_array_elements(c.data) item
    where c.id = 'template_blueprints'
      and item->>'id' = 'talent-partner-program'
  ) then
    raise exception 'Talent Partner blueprint is missing; refusing to create a duplicate template.';
  end if;
end $$;
